mapper.update:
update club_corporate_payee_profile
set verify_status = #{verifyStatus}, verified_by = #{verifiedBy},
    verified_at = #{verifiedAt}, verify_result = #{verifyResult}
where id = #{id} and club_id = #{clubId} and is_current = 1
  and verify_status = 'PENDING' and license_hash = #{licenseHash}
